import { readFile, access, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
const manifest = JSON.parse(await readFile(new URL('./capability.json', import.meta.url), 'utf8'));
let raw = ''; for await (const chunk of process.stdin) raw += chunk;
const request = JSON.parse(raw);
const interpreter = join(request.cacheDir, 'managed-python', 'tree', manifest.runtime.executable);
const probe = path => {
  const result = spawnSync(path, ['-I', '-B', '-c', 'import sys,ssl,sqlite3,zlib,venv,json; print(json.dumps({"version":".".join(map(str,sys.version_info[:3])),"path":sys.executable}))'],
    { cwd: request.workspace, env: process.env, encoding: 'utf8', timeout: 10000, killSignal: 'SIGKILL', maxBuffer: 8192 });
  if (result.status !== 0) return;
  try { const data = JSON.parse(result.stdout); if (data.version === manifest.runtime.version && typeof data.path === 'string' && data.path.startsWith('/')) return data.path; } catch {}
};
let response;
switch (request.operation) {
  case 'check': {
    const installed = await access(join(request.cacheDir, 'managed-python', 'receipt.json')).then(() => true, () => false);
    const path = installed ? probe(interpreter) : probe('python3');
    response = { capabilities: { 'python.runtime': { status: path ? 'ready' : installed ? 'blocked' : 'not_ready',
      checks: [{ name: 'exact_version_stdlib_probe', passed: !!path }],
      ...(path ? { resources: { interpreter: path, version: manifest.runtime.version, source: installed ? 'managed' : 'host' } }
        : { reason: installed ? 'Private Python failed its probe; host loader or shared libraries may be incompatible' : 'Matching Python is unavailable; private pinned runtime preparation is required' }) } } };
    break;
  }
  case 'prepare':
    // Host installs the declared artifact BEFORE this lifecycle entry is called.
    if (!probe(interpreter)) throw new Error('Host-managed runtime was not prepared');
    response = { prepared: true }; break;
  case 'release':
    await rm(request.taskDir, { recursive: true, force: true }); response = { released: true, sharedRuntimeRetained: true }; break;
  default: throw new Error('Resource capability has no invocation tools');
}
process.stdout.write(JSON.stringify(response));
